module TopModule (
    input  wire        clk,
    input  wire        load,
    input  wire [9:0]  data,
    output wire        tc
);

    reg [9:0] count;

    always @(posedge clk) begin
        if (load) begin
            count <= data;
        end else if (count > 10'd0) begin
            count <= count - 10'd1;
        end
    end

    assign tc = (count == 10'd0);

endmodule
